{
  "name": "cache-demo",
  "version": "1.0.0",
  "private": true,
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "build": "turbo run build",
    "lint": "turbo run lint",
    "test": "turbo run test"
  },
  "devDependencies": {
    "turbo": "latest",
    "typescript": "^5.3.3"
  }
}

export class Core {
  private name: string;

  constructor(name: string) {
    this.name = name;
  }

  greet(): string {
    return `Hello from Core: ${this.name}`;
  }

  calculate(a: number, b: number): number {
    return a + b;
  }
}

export const coreVersion = "1.0.0";

import { Core } from "@cache-demo/core";

export class Utils {
  static formatMessage(message: string): string {
    return `[UTILS] ${message}`;
  }

  static createCore(name: string): Core {
    return new Core(name);
  }

  static multiply(a: number, b: number): number {
    return a * b;
  }

  static getTimestamp(): string {
    return new Date().toISOString();
  }
}

export const utilsVersion = "1.0.0";

import { Core, coreVersion } from "@cache-demo/core";
import { Utils, utilsVersion } from "@cache-demo/utils";

export class App {
  private core: Core;

  constructor(name: string) {
    this.core = Utils.createCore(name);
  }

  run(): void {
    console.log(Utils.formatMessage(this.core.greet()));
    console.log(`Core version: ${coreVersion}`);
    console.log(`Utils version: ${utilsVersion}`);
    console.log(`Result: ${this.core.calculate(5, 3)}`);
    console.log(`Multiply: ${Utils.multiply(4, 7)}`);
    console.log(`Timestamp: ${Utils.getTimestamp()}`);
  }
}

const app = new App("Cache Demo");
app.run();

